import { readFileSync, writeFileSync } from 'node:fs';

const order = ['access', 'data', 'dependencies', 'injection', 'platform', 'secrets'];
const rank = { confirmed: 0, likely: 1, possible: 2 }; // lower = higher confidence

const kept = new Map(); // key -> finding
const droppedForDedup = []; // { id, key, keptId }
const allByDept = {};

for (const dept of order) {
  const findings = JSON.parse(readFileSync(`findings/${dept}.json`, 'utf8'));
  allByDept[dept] = findings;
  for (const f of findings) {
    const key = `${f.file}:${f.line}:${f.cwe}`;
    if (!kept.has(key)) {
      kept.set(key, { finding: f, dept, key });
    } else {
      const existing = kept.get(key);
      if (rank[f.confidence] < rank[existing.finding.confidence]) {
        // new one has strictly higher confidence -> replace
        droppedForDedup.push({ id: existing.finding.id, key, keptId: f.id });
        kept.set(key, { finding: f, dept, key });
      } else {
        // existing wins (tie or existing higher)
        droppedForDedup.push({ id: f.id, key, keptId: existing.finding.id });
      }
    }
  }
}

const union = [...kept.values()].map(v => v.finding);
writeFileSync('findings.json', JSON.stringify(union, null, 2) + '\n');

console.log('Total union:', union.length);
console.log('Dropped for dedup:', droppedForDedup.length);
for (const d of droppedForDedup) console.log(`  ${d.id} -> superseded by ${d.keptId} (same ${d.key})`);

const counts = {};
for (const f of union) counts[f.severity] = (counts[f.severity]||0)+1;
console.log('Counts:', counts);
EOF
