import { readFileSync, existsSync } from 'node:fs';

const target = JSON.parse(readFileSync('target.json', 'utf8'));
const files = new Set(Object.keys(target.files));
const basenameMap = new Map();
for (const f of files) {
  const bn = f.split('/').pop();
  if (!basenameMap.has(bn)) basenameMap.set(bn, []);
  basenameMap.get(bn).push(f);
}

const lineCache = new Map();
function linesOf(path) {
  if (!lineCache.has(path)) {
    lineCache.set(path, readFileSync(`${target.root}/${path}`, 'utf8').split('\n'));
  }
  return lineCache.get(path);
}
function resolves(path, line) {
  if (!files.has(path)) return false;
  const l = linesOf(path);
  return Number.isInteger(line) && line >= 1 && line <= l.length;
}

export function checkCitations(text) {
  const problems = [];
  const re = /(?<![\w/.\-])([\w.-]+(?:\/[\w.-]+)*\.\w+):(\d+)\b/g;
  for (const [full, path, lineStr] of text.matchAll(re)) {
    const line = Number(lineStr);
    if (!resolves(path, line)) {
      const bn = path.split('/').pop();
      const candidates = basenameMap.get(bn) || [];
      problems.push({ full, path, line, candidates });
    }
  }
  return problems;
}

// CLI usage: node citecheck.mjs <file>
if (process.argv[2]) {
  const text = readFileSync(process.argv[2], 'utf8');
  const problems = checkCitations(text);
  if (problems.length === 0) {
    console.log('OK: no unresolved citations');
  } else {
    console.log(`${problems.length} unresolved citation(s):`);
    for (const p of problems) console.log(`  "${p.full}" (path=${p.path}, line=${p.line}) candidates=${JSON.stringify(p.candidates)}`);
  }
}
