import { readFileSync, writeFileSync } from 'node:fs';
import { checkCitations } from '/tmp/citecheck.mjs';

const target = JSON.parse(readFileSync('target.json', 'utf8'));
const files = new Set(Object.keys(target.files));
const basenameMap = new Map();
for (const f of files) {
  const bn = f.split('/').pop();
  if (!basenameMap.has(bn)) basenameMap.set(bn, []);
  basenameMap.get(bn).push(f);
}

function repair(text) {
  const re = /(?<![\w/.\-])([\w.-]+(?:\/[\w.-]+)*\.\w+):(\d+)\b/g;
  return text.replace(re, (full, path, lineStr) => {
    if (files.has(path)) return full; // already resolves at path level; line checked separately
    const bn = path.split('/').pop();
    const candidates = basenameMap.get(bn) || [];
    if (candidates.length === 1) return `${candidates[0]}:${lineStr}`;
    return full; // leave as-is; will be caught by checker
  });
}

const union = JSON.parse(readFileSync('findings.json', 'utf8'));
const order = ['critical','high','medium','low','info'];
let out = '';
for (const sev of order) {
  const items = union.filter(f => f.severity === sev).sort((a,b) => a.file.localeCompare(b.file) || a.line - b.line);
  out += `### ${sev}\n\n`;
  for (const f of items) {
    const impact = repair(f.impact);
    const fix = repair(f.fix);
    out += `- \`${f.id}\` — ${f.title} (\`${f.file}:${f.line}\`, ${f.cwe}, ${f.confidence}) — ${impact} ${fix}\n`;
  }
  out += '\n';
}
writeFileSync('/tmp/findings-section2.md', out);
console.log('written');
